package io.quarkiverse.helm.deployment;

import io.smallrye.config.WithDefault;

public interface InitTaskHookConfig {
    /**
     * If enabled, the Jobs generated by the Quarkus init tasks (for example, the Flyway or Liquibase migrations) will be
     * annotated as Helm hooks. Since Jobs are immutable, this allows upgrading the Helm chart when the Job changes
     * (for example, when the container image changes).
     */
    @WithDefault("false")
    boolean enabled();

    /**
     * The Helm hooks to set in the `helm.sh/hook` annotation.
     */
    @WithDefault("post-install,post-upgrade")
    String hooks();

    /**
     * The Helm hook delete policies to set in the `helm.sh/hook-delete-policy` annotation.
     */
    @WithDefault("before-hook-creation")
    String deletePolicy();
}
